      # If the status of a request to destroy a Droplet with its associated resources reported any errors, it can be retried by sending a POST request to the `/v2/droplets/$DROPLET_ID/destroy_with_associated_resources/retry` endpoint. Only one destroy can be active at a time per Droplet. If a retry is issued while another destroy is in progress for the Droplet a 409 status code will be returned. A successful response will include a 202 response code and no content.
      #
      # @param droplet_id [Integer] A unique identifier for a Droplet instance.
      def self.droplets_destroy_retry_with_associated_resources(
        config:,
        droplet_id:,
        request_options: nil
      )
        Validation.validate_range('droplet_id', droplet_id, min: 1)

        SdkClient.request(
          'POST',
          [
            '/v2/droplets/',
            SdkClient.encode_path_segment(droplet_id),
            '/destroy_with_associated_resources/retry'
          ].join,
          config: config,
          decoder: :empty,
          operation_id: 'droplets_destroy_retry_with_associated_resources',
          request_options: request_options,
          errors: { '401' => ::OctridevDigitalocean::Error2, '404' => ::OctridevDigitalocean::Error2, '409' => ::OctridevDigitalocean::Error2, '429' => ::OctridevDigitalocean::Error2, '500' => ::OctridevDigitalocean::Error2, 'default' => ::OctridevDigitalocean::Error2 }
        ).data
      end
    end
  end
